        self._options = options
        self._cache = cache
        self._log = SafeLog(logger or logging.getLogger(LOGGER_NAME))
        seams = seams or TransportSeams()
        self._clock = seams.clock
        self._sleeper = seams.sleeper
        self._random = seams.random
